use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn check(dir:&Path){let v=read(dir.join("exit.json"));assert_eq!(v["success"],true);assert_eq!(v["returncode"],0);for stream in ["stdout","stderr"]{assert_eq!(hash(dir.join(format!("{stream}.log"))),v[format!("{stream}_sha256")].as_str().unwrap());}}
fn suite(dir:&Path,passed:usize,ignored:usize){check(dir);let text=fs::read_to_string(dir.join("stdout.log")).unwrap();let mut total=0;let mut skips=0;let mut summaries=0;for line in text.lines().filter(|l|l.starts_with("test result: ok.")){let words=line.split_whitespace().collect::<Vec<_>>();total+=words[3].parse::<usize>().unwrap();assert_eq!(words[5],"0");skips+=words[7].parse::<usize>().unwrap();assert_eq!(words[11],"0");summaries+=1;}assert!(summaries>0);assert_eq!(total,passed);assert_eq!(skips,ignored);}
fn workflow(root:&Path,count:usize){let result=read(root.join("result.json"));assert_eq!(result["status"],"complete");let names=result["steps"].as_array().unwrap();assert_eq!(names.len(),count);for name in names{let name=name.as_str().unwrap();let dir=root.join(name);check(&dir);if name.ends_with("-verify"){assert!(fs::read_to_string(dir.join("stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));}}}
fn main(){let root=Path::new("/tmp/zopro-retained-deque-buffers");workflow(&root.join("native-v2"),11);workflow(&root.join("preflight"),38);workflow(&root.join("trace-build"),3);workflow(&root.join("trace"),38);
suite(&root.join("native-v2/lifetime-model"),2,0);for mode in ["off","on"]{suite(&root.join("native-v2").join(format!("deque-{mode}")),45,0);suite(&root.join("native-v2").join(format!("rayon-{mode}")),112,2);suite(&root.join("native-v2").join(format!("core-{mode}")),109,0);}suite(&root.join("native-v2/prover"),8,0);
assert_eq!(read(root.join("source-audit.json"))["status"],"passed");assert_eq!(read(root.join("registry-audit.json"))["status"],"passed");assert_eq!(read(root.join("preflight-validation.json"))["status"],"passed");assert_eq!(read(root.join("trace-validation.json"))["status"],"passed");assert_eq!(read(root.join("trace-result.json"))["status"],"passed");
let config=read(root.join("perf-plan.json"));let report=read(root.join("perf/result.json"));assert_eq!(report["status"],"complete");assert_eq!(report["distinct_verified_exports"],219);assert_eq!(config["blocks"],7);assert_eq!(config["monotonic_clock"],true);
let raw=read(root.join("perf/rows.json"));let rows=raw.as_array().unwrap();assert_eq!(rows.len(),219);let mut sdk=0usize;let mut profiles=0;let mut latency=0;let mut samples=0u64;let mut profile_started=false;
for r in rows{let phase=r["phase"].as_str().unwrap();let name=r["case"].as_str().unwrap();let variant=r["variant"].as_str().unwrap();let b=r["block"].as_u64().unwrap();let dir=root.join("perf").join(phase).join(format!("b{b}")).join(name).join(variant);check(&dir.join("run"));check(&dir.join("verify"));assert!(fs::read_to_string(dir.join("verify/stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));assert_eq!(r["summary"]["priming"],3);assert_eq!(r["summary"]["workers"],if name=="1x2-w16"{16}else{32});sdk+=r["samples_ms"].as_array().unwrap().len()+3;if phase=="profile"{profile_started=true;check(&dir.join("symbols"));assert_eq!(r["profile"]["lost_records"],0);assert_eq!(r["profile"]["sampled_pids"].as_array().unwrap().len(),1);samples+=r["profile"]["samples"].as_u64().unwrap();profiles+=1;}else{assert_eq!(phase,"latency");assert!(!profile_started,"latency after sampling began");latency+=1;}}
assert_eq!(sdk,9120);assert_eq!(profiles,9);assert_eq!(latency,210);
let template=read(root.join("all-nine-template.json"));let fixture:BTreeMap<String,String>=template["cases"].as_array().unwrap().iter().map(|c|(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap().to_str().unwrap().into(),c["public_sha256"].as_str().unwrap().into())).collect();let prior:BTreeSet<String>=serde_json::from_value(template["prior_proof_sha256"].clone()).unwrap();
let mut inventory=BTreeMap::<String,String>::new();for file in ["preflight-proof-inventory.json","trace-proof-inventory.json"]{for(name,digest)in read(root.join(file)).as_object().unwrap(){assert_eq!(hash(name),digest.as_str().unwrap());assert!(inventory.insert(name.clone(),digest.as_str().unwrap().into()).is_none());}}for(name,digest)in read(root.join("perf/proof-inventory.json")).as_object().unwrap(){let path=root.join("perf").join(name);assert_eq!(hash(&path),digest.as_str().unwrap());assert!(inventory.insert(path.to_str().unwrap().into(),digest.as_str().unwrap().into()).is_none());}assert_eq!(inventory.len(),510);
let mut unique=BTreeSet::new();for(name,digest)in &inventory{let path=Path::new(name);if path.extension().is_some_and(|e|e=="proof"){assert!(!prior.contains(digest));assert!(unique.insert(digest.to_owned()));assert!(inventory.contains_key(path.with_extension("public").to_str().unwrap()));assert_eq!(fs::metadata(path).unwrap().len(),256);}else{assert_eq!(path.extension().unwrap(),"public");let stem=path.parent().unwrap().file_name().unwrap().to_str().unwrap();assert_eq!(&fixture[stem],digest);}}assert_eq!(unique.len(),255);
let pilot=read(root.join("pilot-result.json"));let passed=pilot["performance_gate_passed"].as_bool().unwrap();let out=json!({"status":if passed{"closed; local speed gate passed, universal/resource/target qualification outstanding"}else{"closed; fixed local speed gate failed"},"performance_gate_passed":passed,"adopted":false,"goal_achieved":false,"sdk_requests":sdk+144,"distinct_gnark_exports":unique.len(),"proof_public_members":inventory.len(),"profiles":profiles,"profile_samples":samples,"lost_records":0,"native_core_each_mode":109,"crossbeam_each_mode":45,"rayon_each_mode":112,"rayon_ignored_each_mode":2,"lifetime_models":2,"raw_tests":2,"cubic_tests":6,"field_tests":"unchanged kernels, inherited33; no new field-suite execution claimed","source_pins":read(root.join("candidate-v2/.xtask/source-pins.json")).as_object().unwrap().len(),"performance_pins":config["pins"].as_object().unwrap().len(),"prior_identities_before_preflight":prior.len(),"failed_checks":pilot["failed_checks"],"original8_aggregate":pilot["original8_aggregate"],"source_audit":read(root.join("source-audit.json")),"initial_failure":read(root.join("failure-v1.json")),"capacity_diagnostic":read(root.join("trace-result.json")),"scope":"All nine SDK shapes32workers plus physical16primary101rounds, complete warm solving/randomness/proving/internal verification/serialization; loading and three primes excluded. Lifetime model covers retention, not the complete queue/scheduler or original generic slot protocol. Additional traced complete SDK runs measure observed buffer capacities; they perturb scheduling and exclude non-queue memory.","decision":if passed{"Preserve positive candidate for resource/portable/concurrentSDK/large/c7a qualification before clean integration; no production adoption yet."}else{"Do not adopt or repeat unchanged. Preserve all samples, code and profiles; use remaining CPU/scheduling evidence for a distinct design."},"limits":"No new portable, pressure, concurrent SDK, large-circuit, C7a or Aeglos qualification/comparison. RSS is whole-process high-water including load/priming. Epoch sample shares are not removable wall time. Historical supplied M5 references, not fresh M5 runs. All-eight tenfold goal remains unmet.","owned_aws_resources":0});
for(name,value)in [("closeout.json",out),("proof-inventory.json",json!(inventory))]{fs::write(root.join(name),format!("{}\n",serde_json::to_string_pretty(&value).unwrap())).unwrap();}println!("CLOSED_VERIFIED SDK{} EXPORTS255 MEMBERS510 PROFILES9 SAMPLES{samples}",sdk+144);}
